UPDATE TBL_QNA_KB SET TITLE='요56 요양병원 지역사회 연계료', SHORT_TITLE='요56 요양병원 지역사회 연계료',
  KEYWORDS='요56 지역사회연계료 AW001 AW002 AW003 환자지원팀 평가료 관리료',
  BODY='요-56 요양병원 지역사회 연계료\n주：1. 환자지원팀(상근하는 의사, 간호사, 사회복지사 각 1인 및 기타 환자지원에 필요한 인력으로 구성)을 설치하여 운영하는 경우에 산정한다.\n   2. 「가」는 입원기간 중 1회 산정하되, 환자 상태의 급격한 변화 등 불가피한 경우 진료기록부에 이를 기록하고 추가 1회 산정한다.\n   3. 「나」, 「다」는 퇴원 시 1회 산정하되 동시에 실시하는 경우에는 주된 항목의 소정점수만 산정한다.\n가. 요양병원 지역사회 연계 평가료(관련 상담 활동 포함) (AW001, 16001) — 233.27점\n나. 요양병원 지역사회 연계 관리료 Ⅰ (AW002, 16002) — 295.76점\n다. 요양병원 지역사회 연계 관리료 Ⅱ (AW003, 16003) — 631.72점',
  SRC_NM='2022 요양병원 수가 실무교육자료(건강보험심사평가원) 26쪽', DOC_PAGE=26 WHERE KB_CODE='pdf-0053';

